public interface PaymentProcessor {
    void process(double amount);
}

public class CreditCardProcessor implements PaymentProcessor {
    private final String cardNumber; // Encapsulation

    public CreditCardProcessor(String cardNumber) { this.cardNumber = cardNumber; }

    @Override
    public void process(double amount) {
        System.out.println("Processing " + amount + " via card ending in " + cardNumber.substring(12));
    }
}

// Polymorphism in action
PaymentProcessor processor = new CreditCardProcessor("1234567812345678");
processor.process(100.0);
